use kiqi_agent::{Agent, AgentEvent};
use kiqi_ai::providers::faux::faux_provider;

let model = faux_provider().model("echo");
let mut agent = Agent::builder(model)
    .system_prompt("You are a helpful assistant.")
    .build();

let mut events = agent.subscribe();
agent.prompt("Hello!").await?;
while let Some(event) = events.recv().await {
    if matches!(event, AgentEvent::AgentEnd { .. }) { break; }
}

use kiqi_tools::{create_read_tool, InMemoryExecutionEnv};

let env = InMemoryExecutionEnv::default();
let read = create_read_tool(env.clone());
let mut agent = Agent::builder(model)
    .tool(read)
    .build();

use kiqi_harness::AgentHarness;

let harness = AgentHarness::builder(agent)
    .session_dir(".ki/sessions")
    .build()
    .await?;
harness.prompt("Summarize this file").await?;

let model = faux_provider().model("echo");
let mut agent = Agent::builder(model)
    .tool(create_read_tool(InMemoryExecutionEnv::default()))
    .build();
agent.prompt("read README.md").await?;

#[async_trait]
pub trait Provider: Send + Sync {
    fn id(&self) -> &str;
    fn models(&self) -> &[Model];
    async fn stream_simple(
        &self,
        model: &Model,
        ctx: &Context,
        opts: &SimpleStreamOptions,
    ) -> AssistantMessageEventStream;
}

#[async_trait]
pub trait AgentTool: Send + Sync {
    fn schema(&self) -> &Tool;
    fn label(&self) -> &str;
    async fn execute(
        &self,
        tool_call_id: &str,
        params: serde_json::Value,
        signal: CancellationToken,
        on_update: Arc<dyn Fn(ToolResultPartial) + Send + Sync>,
    ) -> Result<AgentToolResult, AgentError>;
}

pub trait ExecutionEnv: Send + Sync {
    async fn read_file(&self, path: &Path) -> Result<String>;
    async fn write_file(&self, path: &Path, content: &str) -> Result<()>;
    async fn run_command(&self, command: &str) -> Result<CommandOutput>;
}

